-- // FILESYSTEM // --
local function hasFileSystemSupport()
    local hasWrite = pcall(function() return type(writefile) == "function" end)
    local hasRead = pcall(function() return type(readfile) == "function" end)
    return hasWrite and hasRead
end

local fileSystemSupported = hasFileSystemSupport()

local function saveVerifiedKey(key)
    if not fileSystemSupported then return false end
    pcall(function() writefile("junkie_verified_key.txt", key) end)
end

local function loadVerifiedKey()
    if not fileSystemSupported then return nil end
    local ok, content = pcall(function() return readfile("junkie_verified_key.txt") end)
    return (ok and content) or nil
end

