-- // UTILITIES // --
local Utils = {}

function Utils.Tween(obj, props, time, style, dir)
    local info = TweenInfo.new(time or 0.3, style or Enum.EasingStyle.Quart, dir or Enum.EasingDirection.Out)
    local tween = TweenService:Create(obj, info, props)
    tween:Play()
    return tween
end

function Utils.Corner(parent, radius)
    local c = Instance.new("UICorner")
    c.CornerRadius = UDim.new(0, radius or Config.CornerRadius)
    c.Parent = parent
    return c
end

function Utils.Stroke(parent, color, thickness, transparency)
    local s = Instance.new("UIStroke")
    s.Color = color or Config.Colors.Primary
    s.Thickness = thickness or 1
    s.Transparency = transparency or 0
    s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    s.Parent = parent
    return s
end

function Utils.Gradient(parent, c1, c2, rot)
    local g = Instance.new("UIGradient")
    g.Color = ColorSequence.new{
        ColorSequenceKeypoint.new(0, c1),
        ColorSequenceKeypoint.new(1, c2)
    }
    g.Rotation = rot or 45
    g.Parent = parent
    return g
end

local function SetBlur(enabled)
    local blur = Lighting:FindFirstChild("JunkieBlurRedesign")
    if enabled then
        if not blur then
            blur = Instance.new("BlurEffect")
            blur.Name = "JunkieBlurRedesign"
            blur.Size = 0
            blur.Parent = Lighting
        end
        Utils.Tween(blur, {Size = 24}, 0.5)
    elseif blur then
        Utils.Tween(blur, {Size = 0}, 0.5)
        task.delay(0.5, function() blur:Destroy() end)
    end
end

-- // TOAST SYSTEM // --
local ToastSystem = {Active = {}}
function ToastSystem.Show(parent, msg, type)
    local color = (type == "success" and Config.Colors.Success) or (type == "error" and Config.Colors.Error) or Config.Colors.Warning
    
    local toast = Instance.new("Frame")
    toast.Size = UDim2.new(0, 0, 0, 40) -- Start small
    toast.Position = UDim2.new(0.5, 0, 0.85, 0)
    toast.AnchorPoint = Vector2.new(0.5, 1)
    toast.BackgroundColor3 = Config.Colors.Surface
    toast.BorderSizePixel = 0
    toast.ClipsDescendants = true
    toast.Parent = parent
    
    Utils.Corner(toast, 8)
    Utils.Stroke(toast, color, 1, 0.5)
    
    local lbl = Instance.new("TextLabel")
    lbl.Size = UDim2.new(0, 200, 1, 0)
    lbl.Position = UDim2.new(0.5, 0, 0.5, 0)
    lbl.AnchorPoint = Vector2.new(0.5, 0.5)
    lbl.BackgroundTransparency = 1
    lbl.Text = msg
    lbl.TextColor3 = color
    lbl.Font = Config.Font.Body
    lbl.TextSize = 14
    lbl.Parent = toast
    
    -- Animation
    Utils.Tween(toast, {Size = UDim2.new(0, 280, 0, 45)}, 0.4, Enum.EasingStyle.Back)
    
    task.delay(3, function()
        Utils.Tween(toast, {Size = UDim2.new(0, 0, 0, 45), Transparency = 1}, 0.3)
        task.wait(0.3)
        toast:Destroy()
    end)
end

