    TopGlow.BackgroundColor3 = Config.Colors.Primary
    TopGlow.BorderSizePixel = 0
    TopGlow.Parent = Main
    Utils.Gradient(TopGlow, Config.Colors.Primary, Config.Colors.Accent)
    
    -- Header
    local Header = Instance.new("Frame")
    Header.Size = UDim2.new(1, 0, 0, 50)
    Header.BackgroundTransparency = 1
    Header.Parent = Main
    
    local Title = Instance.new("TextLabel")
    Title.Text = "Fx <font color=\"rgb(124, 58, 237)\">Scripts</font>"
    Title.RichText = true
    Title.Size = UDim2.new(1, -40, 1, 0)
    Title.Position = UDim2.new(0, 20, 0, 0)
    Title.BackgroundTransparency = 1
    Title.Font = Config.Font.Header
    Title.TextSize = 16
    Title.TextColor3 = Config.Colors.TextHigh
    Title.TextXAlignment = Enum.TextXAlignment.Left
    Title.Parent = Header
    
    -- Status Indicator
    local StatusDot = Instance.new("Frame")
    StatusDot.Size = UDim2.fromOffset(8, 8)
    StatusDot.Position = UDim2.new(1, -20, 0.5, 0)
    StatusDot.AnchorPoint = Vector2.new(1, 0.5)
    StatusDot.BackgroundColor3 = Config.Colors.Error
    StatusDot.Parent = Header
    Utils.Corner(StatusDot, 4)
    
    local StatusText = Instance.new("TextLabel")
    StatusText.Text = "LOCKED"
    StatusText.Size = UDim2.new(0, 0, 1, 0)
    StatusText.Position = UDim2.new(1, -35, 0, 0)
    StatusText.AnchorPoint = Vector2.new(1, 0)
    StatusText.BackgroundTransparency = 1
    StatusText.Font = Config.Font.Light
    StatusText.TextSize = 10
    StatusText.TextColor3 = Config.Colors.TextLow
    StatusText.TextXAlignment = Enum.TextXAlignment.Right
    StatusText.Parent = Header
    
    -- Content Container
    local Content = Instance.new("Frame")
    Content.Size = UDim2.new(1, -40, 1, -60)
    Content.Position = UDim2.new(0.5, 0, 0, 50)
    Content.AnchorPoint = Vector2.new(0.5, 0)
    Content.BackgroundTransparency = 1
    Content.Parent = Main
    
    -- Input Box
    local InputContainer = Instance.new("Frame")
    InputContainer.Size = UDim2.new(1, 0, 0, 45)
    InputContainer.BackgroundColor3 = Config.Colors.Surface
    InputContainer.Parent = Content
    Utils.Corner(InputContainer, 8)
    local InputStroke = Utils.Stroke(InputContainer, Config.Colors.Surface, 1, 0)
    
    local KeyIcon = Instance.new("ImageLabel")
    KeyIcon.Size = UDim2.fromOffset(18, 18)
    KeyIcon.Position = UDim2.new(0, 12, 0.5, 0)
    KeyIcon.AnchorPoint = Vector2.new(0, 0.5)
    KeyIcon.Image = Icons.Key
    KeyIcon.ImageColor3 = Config.Colors.TextLow
    KeyIcon.BackgroundTransparency = 1
    KeyIcon.Parent = InputContainer
    
    local InputBox = Instance.new("TextBox")
    InputBox.Size = UDim2.new(1, -40, 1, 0)
    InputBox.Position = UDim2.new(0, 40, 0, 0)
    InputBox.BackgroundTransparency = 1
    InputBox.Text = ""
    InputBox.PlaceholderText = "Paste key here..."
    InputBox.PlaceholderColor3 = Config.Colors.TextLow
    InputBox.TextColor3 = Config.Colors.TextHigh
    InputBox.Font = Config.Font.Body
    InputBox.TextSize = 14
    InputBox.TextXAlignment = Enum.TextXAlignment.Left
    InputBox.Parent = InputContainer
    
    -- Focus Effects
    InputBox.Focused:Connect(function()
        Utils.Tween(InputStroke, {Color = Config.Colors.Primary, Transparency = 0}, 0.2)
        Utils.Tween(KeyIcon, {ImageColor3 = Config.Colors.Primary}, 0.2)
    end)
    
    InputBox.FocusLost:Connect(function()
        Utils.Tween(InputStroke, {Color = Config.Colors.Surface}, 0.2)
        Utils.Tween(KeyIcon, {ImageColor3 = Config.Colors.TextLow}, 0.2)
    end)
    
    -- Buttons Container
    local BtnContainer = Instance.new("Frame")
    BtnContainer.Size = UDim2.new(1, 0, 0, 40)
    BtnContainer.Position = UDim2.new(0, 0, 0, 60)
    BtnContainer.BackgroundTransparency = 1
    BtnContainer.Parent = Content
    
    -- Get Key Button (Secondary)
    local GetKeyBtn = Instance.new("TextButton")
    GetKeyBtn.Size = UDim2.new(0.48, 0, 1, 0)
    GetKeyBtn.BackgroundColor3 = Config.Colors.Surface
    GetKeyBtn.Text = "Get Key"
    GetKeyBtn.TextColor3 = Config.Colors.TextMid
    GetKeyBtn.Font = Config.Font.Body
    GetKeyBtn.TextSize = 13
    GetKeyBtn.AutoButtonColor = false
    GetKeyBtn.Parent = BtnContainer
    Utils.Corner(GetKeyBtn, 8)
    
    -- Redeem Button (Primary)
    local RedeemBtn = Instance.new("TextButton")
    RedeemBtn.Size = UDim2.new(0.48, 0, 1, 0)
    RedeemBtn.Position = UDim2.new(0.52, 0, 0, 0)
    RedeemBtn.BackgroundColor3 = Config.Colors.Primary
    RedeemBtn.Text = "Enter"
    RedeemBtn.TextColor3 = Config.Colors.TextHigh
    RedeemBtn.Font = Config.Font.Body
    RedeemBtn.TextSize = 13
    RedeemBtn.AutoButtonColor = false
    RedeemBtn.Parent = BtnContainer
    Utils.Corner(RedeemBtn, 8)
    local RedeemGrad = Utils.Gradient(RedeemBtn, Config.Colors.Primary, Config.Colors.PrimaryGlow)
    
    -- Footer Info
    local Footer = Instance.new("TextLabel")
    Footer.Size = UDim2.new(1, 0, 0, 20)
    Footer.Position = UDim2.new(0, 0, 1, -10)
    Footer.AnchorPoint = Vector2.new(0, 1)
    Footer.Text = "Powered by Junkie SDK"
    Footer.TextColor3 = Config.Colors.TextLow
    Footer.Font = Config.Font.Light
    Footer.TextSize = 11
    Footer.BackgroundTransparency = 1
    Footer.Parent = Content
    
    -- Hover Effects
    local function AddHover(btn, isPrimary)
        btn.MouseEnter:Connect(function()
            Utils.Tween(btn, {BackgroundTransparency = 0.2}, 0.2)
        end)
        btn.MouseLeave:Connect(function()
            Utils.Tween(btn, {BackgroundTransparency = 0}, 0.2)
        end)
    end
    AddHover(GetKeyBtn)
    AddHover(RedeemBtn)
    
    -- Logic Binding
    GetKeyBtn.MouseButton1Click:Connect(function()
        setclipboard(Junkie.get_key_link())
        ToastSystem.Show(Screen, "Link copied to clipboard", "warning")
    end)
    
    RedeemBtn.MouseButton1Click:Connect(function()
        local k = InputBox.Text:gsub("%s+", "") -- trim
        if k == "" then return end
        
        RedeemBtn.Text = "Checking..."
        Utils.Tween(StatusDot, {BackgroundColor3 = Config.Colors.Warning}, 0.2)
        StatusText.Text = "VERIFYING"
        
        local res = Junkie.check_key(k)
        
        if res and res.valid then
            Utils.Tween(StatusDot, {BackgroundColor3 = Config.Colors.Success}, 0.2)
            StatusText.Text = "AUTHORIZED"
            RedeemBtn.Text = "Success"
            saveVerifiedKey(k)
            getgenv().SCRIPT_KEY = k
            
            ToastSystem.Show(Screen, "Key Verified Successfully", "success")
            
            -- Exit Animation
            task.wait(0.8)
            Utils.Tween(Main, {Size = UDim2.fromOffset(380, 0), Transparency = 1}, 0.5, Enum.EasingStyle.Back, Enum.EasingDirection.In)
            Utils.Tween(Overlay, {BackgroundTransparency = 1}, 0.5)
            SetBlur(false)
            task.wait(0.5)
            Screen:Destroy()
        else
            Utils.Tween(StatusDot, {BackgroundColor3 = Config.Colors.Error}, 0.2)
            StatusText.Text = "INVALID"
            RedeemBtn.Text = "Enter"
            ToastSystem.Show(Screen, res.message or "Invalid Key", "error")
            
            -- Shake Effect
            local x = Main.Position.X.Scale
            local y = Main.Position.Y.Scale
            for i = 1, 4 do
                Main.Position = UDim2.fromScale(x + 0.01, y)
                task.wait(0.03)
                Main.Position = UDim2.fromScale(x - 0.01, y)
                task.wait(0.03)
            end
            Main.Position = UDim2.fromScale(x, y)
        end
    end)
    
    -- Draggable
    local dragging, dragInput, dragStart, startPos
    Header.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            dragStart = input.Position
            startPos = Main.Position
            
            input.Changed:Connect(function()
                if input.UserInputState == Enum.UserInputState.End then
                    dragging = false
                end
            end)
        end
    end)
    
    Header.InputChanged:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
            dragInput = input
        end
    end)
    
    UserInputService.InputChanged:Connect(function(input)
        if input == dragInput and dragging then
            local delta = input.Position - dragStart
            Main.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
        end
    end)
    
    -- Intro Animation
    Main.Size = UDim2.fromOffset(380, 0)
    Utils.Tween(Main, {Size = UDim2.fromOffset(380, 260)}, 0.6, Enum.EasingStyle.Back)
end

-- // INITIALIZATION // --
local saved = loadVerifiedKey()
local check = saved or getgenv().SCRIPT_KEY

if check then
    local res = Junkie.check_key(check)
    if res and res.valid then
        getgenv().SCRIPT_KEY = check
        if not saved then saveVerifiedKey(check) end
    else
        BuildUI()
    end
else
    BuildUI()
end

while not getgenv().SCRIPT_KEY do task.wait(0.1) end

